19	import { Box, Icon } from "@chakra-ui/react";
20	import { useTranslation } from "react-i18next";
21	import { FiChevronRight } from "react-icons/fi";
22	import { LuPlug } from "react-icons/lu";
23	
24	import { Menu } from "src/components/ui";
25	import type { NavItemResponse } from "src/utils/types";
26	
27	import { NavButton } from "./NavButton";
28	import { PluginMenuItem } from "./PluginMenuItem";
29	
30	export const PluginMenus = ({ navItems }: { readonly navItems: Array<NavItemResponse> }) => {
31	  const { t: translate } = useTranslation("common");
32	
33	  if (navItems.length === 0) {
34	    return undefined;
35	  }
36	
37	  const categories: Record<string, Array<NavItemResponse>> = {};
38	  const buttons: Array<NavItemResponse> = [];
39	
40	  navItems.forEach((navItem) => {
41	    if (navItem.category !== null && navItem.category !== undefined) {
42	      categories[navItem.category] = [...(categories[navItem.category] ?? []), navItem];
43	    } else {
44	      buttons.push(navItem);
45	    }
46	  });
47	
48	  if (!buttons.length && !Object.keys(categories).length && navItems.length === 0) {
49	    return undefined;
50	  }
51	
52	  // Show plugins in menu if there are more than or equal to 2
53	  return navItems.length >= 2 ? (
54	    <Menu.Root positioning={{ placement: "right" }}>
55	      <Menu.Trigger asChild>
56	        <NavButton as={Box} icon={LuPlug} title={translate("nav.plugins")} />
57	      </Menu.Trigger>
58	      <Menu.Content>
59	        {buttons.map((navItem) => (
60	          <PluginMenuItem key={navItem.name} {...navItem} />
61	        ))}
62	        {Object.entries(categories).map(([key, menuButtons]) => (
63	          <Menu.Root key={key} positioning={{ placement: "right" }}>
64	            <Menu.TriggerItem display="flex" justifyContent="space-between">
65	              {key}
66	              <Icon as={FiChevronRight} boxSize={4} color="fg.muted" />
67	            </Menu.TriggerItem>
68	            <Menu.Content>
69	              {menuButtons.map((navItem) => (
70	                <PluginMenuItem {...navItem} key={navItem.name} />
71	              ))}
72	            </Menu.Content>
73	          </Menu.Root>
74	        ))}
75	      </Menu.Content>
76	    </Menu.Root>
77	  ) : (
78	    navItems.map((navItem) => <PluginMenuItem {...navItem} key={navItem.name} topLevel={true} />)
79	  );
80	};
81

