[metadata] {"type": "text", "file": {"filePath": "/workspace/repo/airflow-core/src/airflow/ui/src/layouts/Nav/PluginMenus.tsx", "content": "export const PluginMenus = ({ navItems }: { readonly navItems: Array<NavItemResponse> }) => {\n  const { t: translate } = useTranslation(\"common\");\n\n  if (navItems.length === 0) {\n    return undefined;\n  }\n\n  // Items with `nav_top_level` are promoted and always rendered directly on the toolbar.\n  const promotedItems = navItems.filter((navItem) => navItem.nav_top_level === true);\n  const nonPromotedItems = navItems.filter((navItem) => navItem.nav_top_level !== true);\n\n  const categories: Record<string, Array<NavItemResponse>> = {};\n  const buttons: Array<NavItemResponse> = [];\n\n  nonPromotedItems.forEach((navItem) => {\n    if (navItem.category !== null && navItem.category !== undefined) {\n      categories[navItem.category] = [...(categories[navItem.category] ?? []), navItem];\n    } else {\n      buttons.push(navItem);\n    }\n  });\n\n  // Show non-promoted plugins in a submenu only if there are 2 or more of them.\n  const showSubmenu = nonPromotedItems.length >= 2;\n\n  return (\n    <>\n      {promotedItems.map((navItem) => (\n        <PluginMenuItem key={navItem.name} {...navItem} topLevel={true} />\n      ))}\n      {showSubmenu ? (\n        <Menu.Root positioning={{ placement: \"right\" }}>\n          <Menu.Trigger asChild>\n            <NavButton icon={LuPlug} title={translate(\"nav.plugins\")} />\n          </Menu.Trigger>\n          <Menu.Content>\n            {buttons.map((navItem) => (\n              <PluginMenuItem key={navItem.name} {...navItem} />\n            ))}\n            {Object.entries(categories).map(([key, menuButtons]) => (\n              <Menu.Root key={key} positioning={{ placement: \"right\" }}>\n                <Menu.TriggerItem display=\"flex\" justifyContent=\"space-between\">\n                  {key}\n                  <Icon as={FiChevronRight} boxSize={4} color=\"fg.muted\" />\n                </Menu.TriggerItem>\n                <Menu.Content>\n                  {menuButtons.map((navItem) => (\n                    <PluginMenuItem {...navItem} key={navItem.name} />\n                  ))}\n                </Menu.Content>\n              </Menu.Root>\n            ))}\n          </Menu.Content>\n        </Menu.Root>\n      ) : (\n        nonPromotedItems.map((navItem) => (\n          <PluginMenuItem {...navItem} key={navItem.name} topLevel={true} />\n        ))\n      )}\n    </>", "numLines": 60, "startLine": 30, "totalLines": 92}}
